+import path from 'node:path';
+import process from 'node:process';
+
+import { config as loadEnvFile } from 'dotenv';
+
+let envLoaded = false;
+
+function ensureEnvLoaded() {
+  if (!envLoaded) {
+    loadEnvFile();
+    envLoaded = true;
+  }
+}
+
+export function requireEnv(name: string): string {
+  ensureEnvLoaded();
+  const value = process.env[name];
+  if (!value) {
+    throw new Error(
+      `Missing ${name}. Set it in your shell or copy .env.example to .env and provide a value.`,
+    );
+  }
+  return value;
+}
+
+export function optionalEnv(name: string): string | undefined {
+  ensureEnvLoaded();
+  return process.env[name];
+}
+
+export function resolveWorkdir(): string {
+  const custom = optionalEnv('CLAUDE_AGENT_WORKDIR');
+  return custom ? path.resolve(custom) : process.cwd();
+}
