+import type { MessageParam } from '@anthropic-ai/sdk/resources/messages/messages.mjs';
+
+const NEWLINE = '\n';
+
+export class ConsoleRenderer {
+  private liveTextBlocks = new Set<number>();
+  private printedPrefixForBlock = new Set<number>();
+  private streamedOutput = false;
+
+  async handle(message: SDKMessage) {
+    switch (message.type) {
+      case 'system':
+        return this.printSystemMessage(message);
+      case 'user':
+        return this.printUserMessage(message);
+      case 'assistant':
+        return this.printAssistantMessage(message);
+      case 'result':
+        return this.printResultMessage(message);
+      case 'stream_event':
+        return this.printStreamEvent(message);
+      default:
+        console.log('Unrecognized message from SDK:', message);
+    }
+  }
+
+  private printSystemMessage(
+    message:
+      | SDKSystemMessage
+      | SDKCompactBoundaryMessage
+      | SDKHookResponseMessage,
+  ) {
+    if (message.subtype === 'init') {
+      console.log(
+        `Claude ready · cwd=${message.cwd} · model=${message.model} · permissionMode=${message.permissionMode}`,
+      );
+      if (message.tools.length > 0) {
+        console.log(`Tools available: ${message.tools.join(', ')}`);
+      }
+      if (message.mcp_servers.length > 0) {
+        const statuses = message.mcp_servers
+          .map((s) => `${s.name}(${s.status})`)
+          .join(', ');
+        console.log(`MCP servers: ${statuses}`);
+      }
+      return;
+    }
+
+    if (message.subtype === 'compact_boundary') {
+      console.log(
+        `Conversation compressed (${message.compact_metadata.trigger}) at ~${message.compact_metadata.pre_tokens} tokens.`,
+      );
+      return;
+    }
+
+    if (message.subtype === 'hook_response') {
+      console.log(
+        `[hook ${message.hook_event}] ${message.hook_name} · exit=${message.exit_code ?? 0}`,
+      );
+      if (message.stdout) {
+        console.log(indent(`stdout:\n${message.stdout.trimEnd()}`));
+      }
+      if (message.stderr) {
+        console.log(indent(`stderr:\n${message.stderr.trimEnd()}`));
+      }
+    }
+  }
+
+  private printUserMessage(message: SDKUserMessage) {
+    const content = renderUserContent(message.message);
+    console.log(`\nYou:\n${indent(content)}`);
+  }
+
+  private printAssistantMessage(message: SDKAssistantMessage) {
+    const summary = summarizeAssistantMessage(message.message);
+
+    if (!this.streamedOutput && summary.text.length > 0) {
+      console.log(`\nClaude:\n${indent(summary.text)}`);
+    }
+
+    if (summary.thinking) {
+      console.log(indent(`(thinking ${summary.thinking} chars)`));
+    }
+
+    summary.toolUses.forEach((tool) => {
+      console.log(indent(`→ tool ${tool}`));
+    });
+
+    summary.toolResults.forEach((result) => {
+      console.log(indent(`← tool result: ${result}`));
+    });
+
+    this.streamedOutput = false;
+  }
+
+  private printResultMessage(message: SDKResultMessage) {
+    const seconds = (message.duration_ms / 1000).toFixed(1);
+    const cost = message.total_cost_usd.toFixed(4);
+    const usage = message.usage;
+    const tokens = `${usage.input_tokens} in / ${usage.output_tokens} out`;
+
+    if (message.subtype === 'success') {
+      console.log(
+        `\n✅ Completed in ${seconds}s · cost $${cost} · tokens ${tokens}`,
+      );
+    } else {
+      console.log(
+        `\n⚠️ Session ended (${message.subtype}) in ${seconds}s · tokens ${tokens}`,
+      );
+    }
+
+    if (message.permission_denials.length > 0) {
+      console.log(
+        indent(
+          `Permission denials: ${message.permission_denials
+            .map((denial) => denial.tool_name)
+            .join(', ')}`,
+        ),
+      );
+    }
+  }
+
+  private printStreamEvent(message: SDKPartialAssistantMessage) {
+    const event = message.event;
+
+    if (event.type === 'content_block_start') {
+      if (event.content_block.type === 'text') {
+        this.liveTextBlocks.add(event.index);
+        if (!this.printedPrefixForBlock.has(event.index)) {
+          process.stdout.write('\nClaude: ');
+          this.printedPrefixForBlock.add(event.index);
+        }
+      }
+      return;
+    }
+
+    if (
+      event.type === 'content_block_delta' &&
+      isTextDelta(event, this.liveTextBlocks)
+    ) {
+      process.stdout.write(event.delta.text);
+      this.streamedOutput = true;
+      return;
+    }
+
+    if (event.type === 'content_block_stop') {
+      if (this.liveTextBlocks.has(event.index)) {
+        process.stdout.write(NEWLINE);
+        this.liveTextBlocks.delete(event.index);
+        this.printedPrefixForBlock.delete(event.index);
+      }
+      return;
+    }
+  }
+}
+
+function renderUserContent(message: MessageParam): string {
+  if (typeof message.content === 'string') {
+    return message.content;
+  }
+  return message.content
+    .map((block) => {
+      if (block.type === 'text') {
+        return block.text;
+      }
+      return `${block.type}: ${shortJson(block)}`;
+    })
+    .join('\n\n');
+}
+
+function summarizeAssistantMessage(message: BetaMessage) {
+  const textParts: string[] = [];
+  const toolUses: string[] = [];
+  const toolResults: string[] = [];
+  let thinkingChars = 0;
+
+  for (const block of message.content) {
+    switch (block.type) {
+      case 'text':
+        textParts.push(block.text);
+        break;
+      case 'thinking':
+        thinkingChars += block.thinking.length;
+        break;
+      case 'tool_use':
+        toolUses.push(
+          `${block.name}(${block.id}) with ${shortJson(block.input)}`,
+        );
+        break;
+      case 'mcp_tool_use':
+        toolUses.push(
+          `${block.server_name}/${block.name}(${block.id}) ${shortJson(block.input)}`,
+        );
+        break;
+      case 'mcp_tool_result':
+        toolResults.push(renderMcpResult(block));
+        break;
+      default:
+        toolResults.push(`${block.type} ${shortJson(block)}`);
+        break;
+    }
+  }
+
+  return {
+    text: textParts.join('\n\n').trim(),
+    toolUses,
+    toolResults,
+    thinking: thinkingChars > 0 ? thinkingChars : undefined,
+  };
+}
+
+function renderMcpResult(block: BetaMCPToolResultBlock): string {
+  if (typeof block.content === 'string') {
+    return block.content;
+  }
+  const text = block.content.map((entry) => entry.text).join('\n');
+  return block.is_error ? `error: ${text}` : text;
+}
+
+function shortJson(value: unknown, limit = 160): string {
+  const serialized = inspect(value, {
+    breakLength: Infinity,
+    depth: 3,
+    maxArrayLength: 5,
+  });
+  if (serialized.length <= limit) {
+    return serialized;
+  }
+  return `${serialized.slice(0, limit)}…`;
+}
+
+function indent(text: string, prefix = '  '): string {
+  return text
+    .split('\n')
+    .map((line) => `${prefix}${line}`)
+    .join('\n');
+}
+
+function isTextDelta(
+  event: BetaRawContentBlockDeltaEvent,
+  activeBlocks: Set<number>,
+): event is BetaRawContentBlockDeltaEvent & {
+  delta: { type: 'text_delta'; text: string };
+} {
+  return (
+    activeBlocks.has(event.index) &&
+    event.delta.type === 'text_delta' &&
+    typeof (event.delta as { text?: string }).text === 'string'
+  );
+}
