+#!/usr/bin/env tsx
+import process from 'node:process';
+import { createInterface } from 'node:readline/promises';
+
+import type { SDKUserMessage } from '@anthropic-ai/claude-agent-sdk';
+
+import { ConsoleRenderer } from './lib/consoleRenderer.js';
+import { buildUserMessage, runAgentSession } from './lib/runAgent.js';
+
+const renderer = new ConsoleRenderer();
+const rl = createInterface({
+  input: process.stdin,
+  output: process.stdout,
+});
+
+rl.on('SIGINT', () => {
+  rl.close();
+});
+
+console.log('Claude Agent REPL');
+console.log('Type ":exit" to stop, ":help" for tips.\n');
+
+async function* promptStream(): AsyncGenerator<SDKUserMessage> {
+  while (true) {
+    let answer: string;
+    try {
+      answer = await rl.question('You> ');
+    } catch {
+      return;
+    }
+
+    const trimmed = answer.trim();
+    if (trimmed === ':exit') {
+      rl.close();
+      return;
+    }
+    if (trimmed === ':help') {
+      console.log(
+        'Commands: :exit to quit · :clear to ask Claude to reset context (it will receive a reminder).',
+      );
+      continue;
+    }
+    if (trimmed === ':clear') {
+      yield buildUserMessage(
+        'Forget the previous context and acknowledge once you are ready for a new task.',
+      );
+      continue;
+    }
+    if (!trimmed) {
+      continue;
+    }
+    yield buildUserMessage(answer);
+  }
+}
+
+try {
+  await runAgentSession({
+    prompt: promptStream(),
+    options: {
+      includePartialMessages: true,
+      permissionMode: 'default',
+    },
+    onMessage: (message) => renderer.handle(message),
+  });
+} catch (error) {
+  console.error('REPL crashed:', error);
+  process.exitCode = 1;
+} finally {
+  rl.close();
+}
