+      .string()
+      .describe('Optional BCP-47 locale, e.g. "en-US"')
+      .optional(),
+  }),
+  async ({ locale }) => {
+    const formatter = new Intl.DateTimeFormat(locale ?? 'en-US', {
+      dateStyle: 'full',
+      timeStyle: 'long',
+    });
+    return {
+      content: [
+        {
+          type: 'text',
+          text: `At the SDK host: ${formatter.format(new Date())}`,
+        },
+      ],
+    };
+  },
+);
+
+const projectPulseTool = tool(
+  'project_pulse',
+  'Summarize package metadata to give Claude quick context.',
+  z.object({
+    packagePath: z
+      .string()
+      .default('package.json')
+      .describe('Path to a package.json file, relative to the current repo root.'),
+  }),
+  async ({ packagePath }) => {
+    try {
+      const target = path.isAbsolute(packagePath)
+        ? packagePath
+        : path.join(repoRoot, packagePath);
+      const raw = await readFile(target, 'utf8');
+      const pkg = JSON.parse(raw) as {
+        name?: string;
+        version?: string;
+        scripts?: Record<string, string>;
+        dependencies?: Record<string, string>;
+        devDependencies?: Record<string, string>;
+      };
+      const depCount = Object.keys(pkg.dependencies ?? {}).length;
+      const devDepCount = Object.keys(pkg.devDependencies ?? {}).length;
+      const scripts = Object.keys(pkg.scripts ?? {});
+
+      return {
+        content: [
+          {
+            type: 'text',
+            text: `Package ${pkg.name ?? '<unknown>'} v${
+              pkg.version ?? '0.0.0'
+            } · ${depCount} deps · ${devDepCount} devDeps.`,
+          },
+          {
+            type: 'text',
+            text:
+              scripts.length > 0
+                ? `Scripts: ${scripts.join(', ')}`
+                : 'No npm scripts found.',
+          },
+        ],
+        structuredContent: {
+          packagePath: target,
+          scripts: pkg.scripts ?? {},
+        },
+      };
+    } catch (error) {
+      return {
+        content: [
+          {
+            type: 'text',
+            text: `Failed to read ${packagePath}: ${
