+      `\n🔧 Hook: ${input.tool_name} requested with ${JSON.stringify(
+        input.tool_input,
+      ).slice(0, 200)}`,
+    );
+  }
+  return { continue: true };
+};
+
+const postToolHook: HookCallback = async (input) => {
+  if (input.hook_event_name === 'PostToolUse') {
+    console.log(`\n✅ Hook: ${input.tool_name} finished.`);
+  }
+  return { continue: true };
+};
+
+const prompt =
+  process.argv.slice(2).join(' ').trim() ||
+  'Use the available MCP tools to build a tactical TODO list for the current repo.';
+
+try {
+  await runAgentSession({
+    prompt,
+    options: {
+      includePartialMessages: true,
+      permissionMode: 'acceptEdits',
