+        PostToolUse: [{ hooks: [postToolHook] }],
+      },
+      mcpServers: {
+        utilities: localUtilitiesServer,
+      },
+    },
+    onMessage: (message) => renderer.handle(message),
+  });
+} catch (error) {
+  console.error('Tools demo crashed:', error);
+  process.exitCode = 1;
+}
